//! The stack-form assembly string of each opcode (`NAME_S`). Generated by regen.sh.

/// One opcode's stack form: its string, its immediate operands (name and operand class) and its
/// opcode bits (a prefix byte above the low byte).
pub struct Asm {
    pub opcode: u16,
    pub text: &'static str,
    pub names: &'static [&'static str],
    pub kinds: &'static [&'static str],
    pub binary: u32,
}

pub fn find(opcode: u16) -> Option<&'static Asm> {
    ASM_STRINGS.iter().find(|a| a.opcode == opcode)
}

